import os

import pandas as pd
import matplotlib.pyplot as plt


# Final CSV generated by the CPU LZ4 + nvCOMP full-pipeline benchmark.
input_csv = (
    "results/lz4_nvcomp_pipeline/csv_file/"
    "parallel_cpu_lz4_nvcomp_full_pipeline_results.csv"
)

# Store the generated comparison graph alongside the other
# LZ4/nvCOMP pipeline figures.
output_dir = "results/lz4_nvcomp_pipeline/graphs"
output_file = "base_vs_pipe_all_modes_line.png"
output_path = os.path.join(output_dir, output_file)

# Ensure the graph directory exists before saving the figure.
os.makedirs(output_dir, exist_ok=True)


# Load the aggregated benchmark results and normalize CSV headers.
df = pd.read_csv(input_csv)

df.columns = df.columns.str.strip()


# Data-generation modes used by the benchmark to represent
# different levels of compressibility.
modes = ["HIGH", "MEDIUM", "RANDOM"]


# Keep measurements ordered consistently by mode and input size.
df = df.sort_values(["Mode", "MB"])


# Preserve every tested input size for the logarithmic x-axis labels.
all_mb = sorted(df["MB"].unique())


# The uncompressed baseline is independent of compressibility mode.
# Average the baseline measurements across modes for each input size.
df_base = (
    df.groupby("MB", as_index=False)
      .agg({
          "Base_GBps_Avg": "mean",
          "Base_GBps_StdDev": "mean"
      })
      .sort_values("MB")
)


# Create one figure containing the baseline and all compressed-pipeline modes.
plt.figure(figsize=(12, 6))


# Plot the uncompressed baseline throughput together with its
# measured standard-deviation error bars.
plt.errorbar(
    df_base["MB"],
    df_base["Base_GBps_Avg"],
    yerr=df_base["Base_GBps_StdDev"],
    marker="o",
    linewidth=2,
    capsize=5,
    label="BASE"
)


# Plot effective LZ4 + nvCOMP pipeline throughput separately for
# HIGH, MEDIUM, and RANDOM input compressibility.
for mode in modes:

    df_mode = df[df["Mode"] == mode].sort_values("MB")

    plt.errorbar(
        df_mode["MB"],
        df_mode["Pipe_Eff_GBps_Avg"],
        yerr=df_mode["Pipe_Eff_GBps_StdDev"],
        marker="o",
        linewidth=2,
        capsize=5,
        label=f"PIPE ({mode})"
    )


# Use a base-2 logarithmic x-axis because the tested data sizes
# increase approximately by powers of two.
plt.xlabel("Data Size (MB)")
plt.ylabel("Effective Throughput (GB/s)")
plt.title("Baseline vs LZ4 + nvCOMP Pipeline Across Data Modes")

plt.xscale("log", base=2)

# Show the actual benchmark input sizes rather than generic log ticks.
plt.xticks(all_mb, all_mb)

plt.grid(axis="y", linestyle="--", alpha=0.5)

plt.legend()


# Tighten the layout before writing the high-resolution graph.
plt.tight_layout()

plt.savefig(output_path, dpi=300)

print(f"Saved graph to: {output_path}")

plt.show()


# Run from the repository root:
#
# python3 <path-to-this-script>.py
#
# Input:
# results/lz4_nvcomp_pipeline/csv_file/
# parallel_cpu_lz4_nvcomp_full_pipeline_results.csv
#
# Output:
# results/lz4_nvcomp_pipeline/graphs/base_vs_pipe_all_modes_line.png